<?php
namespace Tests\Unit;use App\Models\{TransportRoute,TransportSchedule,TransportScheduleDay};use App\Services\{TransportAuditService,TransportScheduleGeneratorService,TransportSchedulingConflictService};use Illuminate\Support\Collection;use Tests\TestCase;
class TransportScheduleGeneratorTest extends TestCase{private function schedule(array$days,string$start='06:00',string$arrival='07:00'):TransportSchedule{$s=new TransportSchedule(['company_id'=>999999,'starts_on'=>'2026-08-18','ends_on'=>'2026-08-31','default_start_time'=>$start,'default_arrival_time'=>$arrival,'arrival_next_day'=>false,'service_type'=>'pickup','shift'=>'morning']);$s->setRelation('days',new Collection(array_map(fn($d)=>new TransportScheduleDay(['day_of_week'=>$d]),$days)));$s->setRelation('route',new TransportRoute(['name'=>'Ruta Norte','origin'=>'Colegio','destination'=>'Norte']));return$s;}private function generator():TransportScheduleGeneratorService{return new TransportScheduleGeneratorService(new TransportSchedulingConflictService(),new TransportAuditService());}public function test_weekday_recurrence_resolves_exact_dates():void{$preview=$this->generator()->preview($this->schedule([1,2,3,4,5]));$this->assertCount(10,$preview);$this->assertSame('2026-08-18',$preview[0]['service_date']);$this->assertSame('2026-08-31',$preview[9]['service_date']);}public function test_monday_only_rule():void{$preview=$this->generator()->preview($this->schedule([1]));$this->assertSame(['2026-08-24','2026-08-31'],array_column($preview,'service_date'));}public function test_service_can_cross_midnight():void{$preview=$this->generator()->preview($this->schedule([2],'23:00','01:00'));$this->assertTrue($preview[0]['scheduled_arrival_at']->isNextDay());$this->assertSame('2026-08-19 01:00',$preview[0]['scheduled_arrival_at']->format('Y-m-d H:i'));}}
